          "line": 9,
          "text": "    entity = VehicleTelemetry.FromString(base64.b64decode(request['payload'], validate=True))"
        },
        {
          "line": 10,
          "text": "    sample = VehicleTelemetry(vehicle_id=request['vehicle_id'], speed_mps=request['speed'])"
        },
        {
          "line": 11,
          "text": "    fields = {'vehicle_id': entity.vehicle_id, 'speed_mps': entity.speed_mps}"
        },
        {
          "line": 12,
          "text": "    return {'fields': fields, 'speeding': entity.speed_mps > 30.0,"
        },
        {
          "line": 13,
          "text": "            'constructed_payload': base64.b64encode(sample.SerializeToString()).decode()}"
        },
